function applyTheme(theme,persist=false){
  selectedTheme=normalizeTheme(theme);
  if(persist)saveVisualTheme(selectedTheme);
  document.documentElement.classList.toggle('theme-night',isNightTheme());
  document.documentElement.classList.toggle('theme-sunny',isSunnyTheme());
  document.body.classList.toggle('theme-night',isNightTheme());
  document.body.classList.toggle('theme-sunny',isSunnyTheme());
  refreshThemeCache();
  const logo=document.querySelector('.brand-logo');
  if(logo)logo.src=themeLogo();
  if(state===S.SELECT)updateSongPreview();
}
