function vnCharacterKey(node){const s=node.character||node.speaker||'';const sl=s.toLowerCase();if(!s||['你','旁白','内心','系统','订单','后厨'].includes(s))return'';if(sl.includes('yuzu')||sl.includes('柚子'))return'yuzu';if(sl.includes('student')||sl.includes('学生')||s==='林小末')return'student_girl';const VIP_MAP={'阿晟':'ashen','老方':'laofang','猫小姐':'miss_cat','顾薇':'guiwei','谢音':'xieyin','程晚':'chengwan','远哥':'yuange','面具':'mianju','老弦':'laoxian','老贝':'laobei','焰子':'yanzi','小兵':'xiaobing','老宋':'laosong','月叔':'yueshu','无名':'wuming','流浪者':'wanderer'};return VIP_MAP[s]||''}
function vnDefaultExpression(key,node){if(node.expr)return node.expr;if(key==='yuzu'){const t=node.text||'';if(/来了！/.test(t))return'panic';if(/（叹气）/.test(t))return'sigh';if(/还不错嘛|平安度过|首单没砸|搞定收工|老规矩|新人不排/.test(t))return'relieved';if(/别太信|算不上夸张|到时你就知道了/.test(t))return'serious';if(/别贫嘴|叫你半天|我要的柠檬汁/.test(t))return'annoyed';if(/拍了拍|一步步来|照着指南|都记牢了/.test(t))return'smile';if(/不叫了|没有|瞪过|冷柜|榨汁机呢|先别|明天再上课/.test(t))return'deadpan';if(/口水|脸红|炽热的目光|深情|少年|巨响|天下第一|幸灾乐祸|机器人女郎|跑路吧|催作业/.test(t))return'teasing';return'neutral'}if(key==='student_girl'){if(/好快|柠檬味诶|两分钟|可别告诉老师|羡慕的/.test(node.text||''))return'smile';if(/忧伤|马失前蹄|担待喽|建交|补课/.test(node.text||''))return'awkward';return'tired'}return'neutral'}
