function drawConfetti(info){resultPanel.querySelectorAll('.confetti').forEach(e=>e.remove());if(!info)return;const colors=['#8cffc1','#ffd98c','#ff8aa6','#80b7ff','#a77cff'];for(let i=0;i<34;i++){const c=document.createElement('span');c.className='confetti';c.style.left=(6+Math.random()*88)+'%';c.style.background=colors[i%colors.length];c.style.animationDelay=(Math.random()*.45)+'s';c.style.animationDuration=(1.25+Math.random()*.9)+'s';resultPanel.appendChild(c)}}
function setResultActions(mode){const retry=$('retryButton'),menu=$('menuButton'),end=$('endDayButton'),home=$('resultHomeButton');home.textContent='\u56de\u4f4f\u5904';home.onclick=showTitle;if(mode==='day'){retry.textContent='\u5f00\u59cb\u65b0\u4e00\u5929';retry.onclick=advanceDay;menu.textContent='\u5347\u7ea7\u5e97\u94fa';menu.onclick=showUpgradePanel;end.classList.add('hidden');menu.classList.remove('hidden');retry.classList.remove('quiet')}else if(dayRun.active){const done=dayRun.aborted||dayRun.index>=dayRun.queue.length;retry.textContent=done?'\u8fdb\u5165\u65e5\u7ed3':'\u4e0b\u4e00\u73ed';retry.onclick=continueDayRun;menu.classList.add('hidden');end.textContent='\u63d0\u524d\u6536\u5de5';end.onclick=showDaySummary;end.classList.toggle('hidden',done||currentShiftIsTutorial());retry.classList.remove('quiet')}else{retry.textContent='\u518d\u6765\u4e00\u73ed';retry.onclick=start;menu.textContent='\u6362\u4e00\u9996';menu.onclick=showMenuEdit;end.textContent='\u7ed3\u675f\u4eca\u5929';end.onclick=showDaySummary;menu.classList.remove('hidden');end.classList.remove('hidden')}retry.classList.toggle('quiet',mode==='day')}
